  function day(title, track, minutes, objective, recall, lesson, steps, hint, solution, check, deliverable, refs, code, study) {
    const [question, options, answer, explanation] = check;
    const resources = refs.map(key => ({ label: notes[key][0], url: notes[key][1] }));
    const result = { title, track, minutes, objective, recall, lesson, steps, hint, solution,
      check: { question, options, answer, explanation }, deliverable, resources };
    if (code) result.code = { language: code[0], text: code[1] };
    if (typeof study === 'string') {
      result.file = 'labs/primer/study_' + study + '.cpp';
      result.run = 'powershell -ExecutionPolicy Bypass -File .\\labs\\primer\\run.ps1 -Study ' + study;
    } else if (study) {
      result.file = study.file;
      result.run = study.run;
    }
    return result;
  }

